import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import type { Grade } from '../people/people';
import type { Claim } from '../claims/claims';

/**
 * A grade's rate: a percent with two decimals, from a date (yyyy-MM-dd; '' when it applies from the
 * beginning of time).
 */
export type Rate = { grade: Grade; pct: string; from: string };

export const ratesKey = (sheetId: string) => ['sheet', sheetId, 'rates'] as const;

/** The sheet's rates, by grade then from-date (none first). */
export function useRates(sheetId: string) {
  return useQuery({
    queryKey: ratesKey(sheetId),
    queryFn: async () =>
      (await getJson<{ rates: Rate[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`)).rates,
  });
}

/**
 * A grade's rate in force on a date (yyyy-MM-dd): the one whose from-date is the latest on or
 * before it. Null when the date is before every rate the grade has (or it has none).
 */
export function rateOn(rates: Rate[], grade: Grade, date: string): string | null {
  let best: Rate | null = null;
  for (const r of rates) {
    if (r.grade !== grade || r.from > date) continue;
    if (best === null || r.from > best.from) best = r;
  }
  return best?.pct ?? null;
}

/** The sheet's rate for a grade on a date, or null when none is in force (or the rates are not read yet). */
export function useGradeRate(sheetId: string, grade: Grade, date: string): string | null {
  return rateOn(useRates(sheetId).data ?? [], grade, date);
}

/** A percent as a rate takes it: 0.00 or more, with up to two decimals. */
export const PCT = /^\d+(\.\d{1,2})?$/;

export const NA = 'n/a';

/** A two-decimal number as a whole count of hundredths. */
function hundredths(value: string): bigint {
  const [whole, frac = ''] = value.trim().split('.');
  return BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
}

function showCents(cents: bigint): string {
  return `${cents / 100n}.${(cents % 100n).toString().padStart(2, '0')}`;
}

/**
 * An amount times a rate, divided by 100, rounded half up to two decimals; n/a with no rate.
 * Worked in whole numbers so no floating-point error creeps in (amounts and rates are never
 * negative, so half up is half away from zero).
 */
export function due(amount: string, pct: string | null): string {
  if (pct === null) return NA;
  // cents × basis points is the due in millionths of a unit: 10000 of them to the cent.
  const x = hundredths(amount) * hundredths(pct);
  return showCents((x + 5000n) / 10000n);
}

/** Due values added up, skipping n/a. */
export function sumDue(values: string[]): string {
  return showCents(values.filter((v) => v !== NA).reduce((n, v) => n + hundredths(v), 0n));
}

/** A claim's due: the one fixed when it was settled, else its amount at the rate in force on its date. */
export function claimDue(claim: Claim, pct: string | null): string {
  return claim.due !== '' ? claim.due : due(claim.amount, pct);
}

import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A claim's status: DRAFT when made, then OPEN, then SETTLED; a DRAFT or OPEN claim may be VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

/**
 * A claim: its amount with two decimals, its date (yyyy-MM-dd), its note, its status and its
 * number on the sheet (given when it is opened; '' for a draft or a voided claim), and its due as
 * fixed when it was settled ('' while its due is live: unsettled, or settled with no rate).
 */
export type Claim = {
  id: string;
  personId: string;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string;
  due: string;
};

/** Whether a claim counts toward claimed, due-total and every total: only OPEN and SETTLED do. */
export const counts = (c: Claim) => c.status === 'OPEN' || c.status === 'SETTLED';

export const claimsKey = (sheetId: string) => ['sheet', sheetId, 'claims'] as const;

/** The sheet's claims, newest first. */
export function useClaims(sheetId: string) {
  return useQuery({
    queryKey: claimsKey(sheetId),
    queryFn: async () =>
      (await getJson<{ claims: Claim[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`)).claims,
  });
}

/** An amount as a claim takes it: 0.00 or more, with up to two decimals. */
export const AMOUNT = /^\d+(\.\d{1,2})?$/;

/**
 * The amounts of the claims that count (OPEN and SETTLED) added up, in whole cents so no rounding
 * creeps in, shown with two decimals.
 */
export function sumAmounts(claims: Claim[]): string {
  const cents = claims.filter(counts).reduce((n, c) => n + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
import { SheetBody } from '../../slots/defs/sheetBody';
import { sumAmounts, useClaims } from './claims';

// The sheet's claimed-total: everyone's claims added up.
function ClaimedTotal({ sheetId }: { sheetId: string }) {
  const claims = useClaims(sheetId);
  return (
    <p>
      Claimed in all: <strong data-testid="rollup-claimed-total">{sumAmounts(claims.data ?? [])}</strong>
    </p>
  );
}

export const contribution = SheetBody.fill({ order: 10, Component: ClaimedTotal });
